    tall = b - a >= e - d
    if tall:
        r0, r1, c0, c1 = a - 3, b + 3, d - 3, e + 2
    else:
        r0, r1, c0, c1 = a - 1, b + 1, d - 1, e + 1
    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    n = max(b - a + 1, e - d + 1)
    square = [[0] * n for _ in range(n)]
    for r in range(a, b + 1):
        for c in range(d, e + 1):
            square[r - a][c - d] = grid[r][c]
    rotated = [[square[n - 1 - c][r] for c in range(n)] for r in range(n)] if not tall else [[square[c][n - 1 - r] for c in range(n)] for r in range(n)]
    for r in range(n):
        for c in range(n):
            out[a - r0 + r][d - c0 + c] = rotated[r][c]
